\label{lem:a}
Suppose that a parabolic connection $(E_*, D)$ is 
irreducible.  Then $(E_*, D)$ is stable.

\label{thm:1}
 The morphisms defined in \eqref{eq:a25.1} and \eqref{eq:a25.2}
$$\ensuremath{\mathrm{Pic} (\ensuremath{\mathcal{M}}(r, d, \alpha))} \xrightarrow{\pi^*} 
\ensuremath{\mathrm{Pic} (\ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha))} \xleftarrow{\iota^*} \ensuremath{\mathrm{Pic} (\ensuremath{\mathcal{M}}_{pc}(r, d, \alpha))}$$
are isomorphisms.

\mbox{}
\label{rmk:1} There is an alternative way of proving  that $\pi^*$ as defined in \eqref{eq:a25.2} is an 
isomorphism, without using the compactification 
$\ensuremath{\mathbf{P}} (\ensuremath{\mathcal{W}})$ of $\ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha)$.
Recall that if we have an algebraic morphism 
 between varieties $f : \ensuremath{\mathcal{X}} \longrightarrow \ensuremath{\mathcal{S}}$
 such that the fibres are geometrically connected, then 
 there exits an exact sequence
 \begin{equation}
 \label{eq:b23}
 1 \to \ensuremath{\mathrm{Pic} (\ensuremath{\mathcal{S}})} \to \ensuremath{\mathrm{Pic} (\ensuremath{\mathcal{X}})} \to \text{Pic}_{\ensuremath{\mathcal{X}}/\ensuremath{\mathcal{S}}}(\ensuremath{\mathcal{S}}) \to \text{Br}(\ensuremath{\mathcal{S}}),
 \end{equation}
 of groups, where $\text{Pic}_{\ensuremath{\mathcal{X}}/\ensuremath{\mathcal{S}}}(\ensuremath{\mathcal{S}})$ denote the group of section of relative Picard scheme 
 $\text{Pic}_{\ensuremath{\mathcal{X/\ensuremath{\mathcal{S}}}}}$ over $S$, and 
 $\text{Br}(\ensuremath{\mathcal{S}})$ denote the Brauer group of $\ensuremath{\mathcal{S}}$.
 In our set up, we have following exact sequence
 corresponding to the morphism $\pi$  defined in \eqref{eq:a21.1}
 \begin{equation}
 \label{eq:b24}
 1 \to \ensuremath{\mathrm{Pic} (\ensuremath{\mathcal{M}}(r, d, \alpha))} \to \ensuremath{\mathrm{Pic} (\ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha))}
 \to \text{Pic}_{\ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha)/ \ensuremath{\mathcal{M}}(r, d, \alpha
 )}(\ensuremath{\mathcal{M}}(r, d, \alpha))
 \end{equation}

 Since, each fibre of the morphism $\pi$ (see \eqref{eq:a21.1}) is an affine space, the group 
 $\text{Pic}_{\ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha)/ \ensuremath{\mathcal{M}}(r, d, \alpha
 )}(\ensuremath{\mathcal{M}}(r, d, \alpha))$ is trivial.

\label{prop:1}
$\ensuremath{\mathrm{Pic} (\ensuremath{\mathcal{M}}_{pc}(r, \alpha, \xi))} \cong \ensuremath{\mathrm{Pic} (\ensuremath{\mathcal{M}}(r,
 \alpha, \xi))}.$

\label{thm:2} 
 Let $L$ be an ample line bundle over $\ensuremath{\mathcal{M}}$, and 
 $\ensuremath{\mathcal{O}_{\ensuremath{\mathcal{C}}(L)}}$ denote the sheaf of regular functions on $\ensuremath{\mathcal{C}}(L)$. Then
 \begin{equation}
 \label{eq:40.1}
 \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{C}}(L),\ensuremath{\mathcal{O}_{\ensuremath{\mathcal{C}}(L)}})} = \ensuremath{\mathbb{C}}
 \end{equation}

Consider the dual of the  Atiyah exact sequence in \eqref{eq:a40}, that is, 
 \begin{equation}
\label{eq:a41}
0 \to T^*\ensuremath{\mathcal{M}} 
\xrightarrow{\sigma^*} 
\ensuremath{\mathrm{At} (L)}^* \xrightarrow{\imath^*}   \ensuremath{\mathcal{O}_{\ensuremath{\mathcal{M}}}} \to 0.
\end{equation}

Consider $\ensuremath{\mathcal{O}_{\ensuremath{\mathcal{M}}}}$ as the trivial line 
bundle $\ensuremath{\mathcal{M}} \times \ensuremath{\mathbb{C}}$. Let $$ \alpha : \ensuremath{\mathcal{M}} \to \ensuremath{\mathcal{M}} \times \ensuremath{\mathbb{C}}$$ be a
holomorphic section of the trivial line bundle defined by $x \mapsto (x,1)$.
Let $Y = \ensuremath{\mathrm{Im} (\alpha)} \subset \ensuremath{\mathcal{M}} \times \ensuremath{\mathbb{C}}$ be the image of $\alpha$. Then 
$$\ensuremath{\mathcal{C}}(L) = {\imath^*}^{-1}Y \subset \ensuremath{\mathrm{At} (L)}^*.$$

In fact, for every open subset $U \subset \ensuremath{\mathcal{M}}
$, a holomorphic section of $\ensuremath{\mathcal{C}}(L)|_{U}$ over $U$ gives a holomorphic
splitting of the Atiyah exact sequence \eqref{eq:a40}, 
associated to the holomorphic vector bundle $L|
_{U} \to U$. 
 For instance, suppose $\tau: U \to \ensuremath{\mathcal{C}}(L)|
_{U}$ is a holomorphic section. Then $\tau$ will be a 
holomorphic section of $\ensuremath{\mathrm{At} (L)}^*|_{U}$  over $U$, 
because $ \ensuremath{\mathcal{C}}(L) =
{\imath^*}^{-1}Y \subset \ensuremath{\mathrm{At} (L)}^*$. Since $$ 
 \tau \circ \imath =  \imath^*(\tau) = \ensuremath{\mathbf{1}_{U}},$$ so we 
 get a holomorphic  splitting $\tau$ of the Atiyah 
 exact sequence \eqref{eq:a40}
 associated to $L|_{U}.$ Thus, $L|_{U}$ admits 
 a holomorphic connection. 
 Conversely, given any splitting of Atiyah exact sequence 
 \eqref{eq:a40} over an open subset $U \subset \ensuremath{\mathcal{M}}$, we get a holomorphic section of $\ensuremath{\mathcal{C}}(L)|_{U}$ over $U$.

Let 
 $\ensuremath{\mathbf{P}}(\ensuremath{\mathrm{At} (L)})$ be the projectivization of 
$\ensuremath{\mathrm{At} (L)}$, that is, $\ensuremath{\mathbf{P}}(\ensuremath{\mathrm{At} (L)})$ parametrises hyperplanes in $\ensuremath{\mathrm{At} (L)}$.
Let $\ensuremath{\mathbf{P}}({T \ensuremath{\mathcal{M}}})$ be the projectivization of the tangent bundle $T\ensuremath{\mathcal{M}}$. 
Notice that $\ensuremath{\mathbf{P}}(T\ensuremath{\mathcal{M}})$ is a subvariety of 
$\ensuremath{\mathbf{P}} (\ensuremath{\mathrm{At} (L)})$, and  $\ensuremath{\mathbf{P}}(T\ensuremath{\mathcal{M}})$ is the zero
locus of the of a section of the tautological line bundle
$\ensuremath{\mathcal{O}_{\ensuremath{\mathbf{P}} (\ensuremath{\mathrm{At} (L)})}}(1)$. Now, observe that
$$\ensuremath{\mathcal{C}}(L) = \ensuremath{\mathbf{P}}(\ensuremath{\mathrm{At} (L)}) \setminus \ensuremath{\mathbf{P}}(T \ensuremath{\mathcal{M}}).$$ 
So we have 
\begin{equation}
\label{eq:a42}
\ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{C}}(L),\ensuremath{\mathcal{O}_{\ensuremath{\mathcal{C}}(L)}})} =
\varinjlim_{k \geq 0} \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathbf{P}} (\ensuremath{\mathrm{At} (L)}),\ensuremath{\mathcal{O}_{\ensuremath{\mathbf{P}} \ensuremath{\mathrm{At} (L)}}}(k))}.
\end{equation}


Since for any finite dimensional vector space $V$ over 
$\ensuremath{\mathbb{C}}$ and for every $k \geq 0$, we have 
$\ensuremath{\mathrm{H}^{0}(\ensuremath{\mathbf{P}}(V),\ensuremath{\mathcal{O}_{\ensuremath{\mathbf{P}}(V)}}(k))} = \ensuremath{\mathcal{S}}ym^k(V)$, 
where $\ensuremath{\mathcal{S}}ym^k(V)$ denote the $k$-th symmetric powers of $V$. We get a natural isomorphism 
$$\ensuremath{\mathrm{H}^{0}(\ensuremath{\mathbf{P}} (\ensuremath{\mathrm{At} (L)}), \ensuremath{\mathcal{O}_{\ensuremath{\mathbf{P}} \ensuremath{\mathrm{At} (L)}}}(k))} \cong \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}}, \ensuremath{\mathcal{S}}ym^k\ensuremath{\mathrm{At} (L)})},$$
where $\ensuremath{\mathcal{S}}ym^k\ensuremath{\mathrm{At} (L)}$ denote the $k$-the symmetric powers of $\ensuremath{\mathrm{At} (L)}$,
and hence from \eqref{eq:a42}, we get
\begin{equation}
\label{eq:a43}
\ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{C}}(L),\ensuremath{\mathcal{O}_{\ensuremath{\mathcal{C}}(L)}})} = \varinjlim_{k} \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}}, \ensuremath{\mathcal{S}}ym^k\ensuremath{\mathrm{At} (L)})}.
\end{equation}


The symbol operator 
\begin{equation*}
\label{eq:a44}
\sigma:\ensuremath{\mathrm{At} (L)} \to   T\ensuremath{\mathcal{M}}
\end{equation*}
as described  in  \eqref{eq:a39},
 induces a morphism 
\begin{equation*}
\label{eq:a45}
\ensuremath{\mathcal{S}}ym^k(\sigma): \ensuremath{\mathcal{S}}ym^k \ensuremath{\mathrm{At} (L)} \to 
\ensuremath{\mathcal{S}}ym^k T \ensuremath{\mathcal{M}}
\end{equation*}
on $k$-th symmetric powers of bundles.
In view of the following composition 
\begin{equation*}
\ensuremath{\mathcal{S}}ym^{k-1} \ensuremath{\mathrm{At} (L)} = \ensuremath{\mathcal{O}_{\ensuremath{\mathcal{M}}}} \otimes \ensuremath{\mathcal{S}}ym^{k-1} \ensuremath{\mathrm{At} (L)} \hookrightarrow 
\ensuremath{\mathrm{At} (L)} \otimes \ensuremath{\mathcal{S}}ym^{k-1} \ensuremath{\mathrm{At} (L)} \to 
\ensuremath{\mathcal{S}}ym^{k} \ensuremath{\mathrm{At} (L)},
\end{equation*}
we have 
\begin{equation*}
\label{eq:a46}
\ensuremath{\mathcal{S}}ym^{k-1} \ensuremath{\mathrm{At} (L)} \subset \ensuremath{\mathcal{S}}ym^k \ensuremath{\mathrm{At} (L)}
~~~ \mbox{for all}~ k \geq 1.
\end{equation*}
In fact, we have the symbol exact sequence associated to 
$L$ over
$\ensuremath{\mathcal{M}}$,
\begin{equation}
\label{eq:a47}
0 \to \ensuremath{\mathcal{S}}ym^{k-1} \ensuremath{\mathrm{At} (L)} \to \ensuremath{\mathcal{S}}ym^{k} \ensuremath{\mathrm{At} (L)} \xrightarrow{\ensuremath{\mathcal{S}}ym^k (\sigma)} \ensuremath{\mathcal{S}}ym^k T \ensuremath{\mathcal{M}} \to 0.
\end{equation}



In other words, we get a filtration 
\begin{equation*}
\label{eq:32}
0 \subset \ensuremath{\mathcal{S}}ym^0 \ensuremath{\mathrm{At} (L)} \subset \ensuremath{\mathcal{S}}ym^1 
\ensuremath{\mathrm{At} (L)} \subset \ldots \subset \ensuremath{\mathcal{S}}ym^{k-1} 
\ensuremath{\mathrm{At} (L)} \subset \ensuremath{\mathcal{S}}ym^k \ensuremath{\mathrm{At} (L)} \subset 
\ldots
\end{equation*}

 such that 
 \begin{equation}
 \label{eq:33}
 \ensuremath{\mathcal{S}}ym^{k} \ensuremath{\mathrm{At} (L)} / \ensuremath{\mathcal{S}}ym^{k-1} \ensuremath{\mathrm{At} (L)} 
 \cong \ensuremath{\mathcal{S}}ym^k T \ensuremath{\mathcal{M}}~~~ \mbox{for all}~ k 
 \geq 1.
 \end{equation}



To prove \eqref{eq:40.1}, it is enough to show that 
\begin{equation}
\label{eq:35}
\ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^{k-1}\ensuremath{\mathrm{At} (L)})}
\cong \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^k\ensuremath{\mathrm{At} (L)})}
~~~ \mbox{for all}~ k \geq 1.
\end{equation}








We have the following commutative diagram
\begin{equation}
\label{eq:cd1}
\xymatrix@C=2em{
0 \ar[r] & \ensuremath{\mathcal{S}}ym^{k-1} \ensuremath{\mathrm{At} (L)} \ar[d] \ar[r] & \ensuremath{\mathcal{S}}ym
^k \ensuremath{\mathrm{At} (L)} 
\ar[d] \ar[r]^{\sigma_k} &  \ensuremath{\mathcal{S}}ym^k T \ensuremath{\mathcal{M}} \ar[d] \ar[r] & 0 \\
0 \ar[r] &  \ensuremath{\mathcal{S}}ym^{k-1} T \ensuremath{\mathcal{M}} \ar[r] & 
\frac{\ensuremath{\mathcal{S}}ym^k \ensuremath{\mathrm{At} (L)}}{\ensuremath{\mathcal{S}}ym^{k-2} \ensuremath{\mathrm{At} (L)}} \ar[r] &  \ensuremath{\mathcal{S}}ym^k T \ensuremath{\mathcal{M}} \ar[r] & 0 
}
\end{equation}

which gives the following commutative 
diagram of long exact sequences
\begin{equation}
\label{eq:cd2}
\xymatrix@C=2em{
\cdots \ar[r] & \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^k T 
\ensuremath{\mathcal{M}})} \ar[d] \ar[r]^{\delta'_{k}} & \ensuremath{\mathrm{H}^{1}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^{k-1}\ensuremath{\mathrm{At} (L)})} \ar[d] 
\ar[r] & \cdots  \\
\cdots \ar[r] & \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^k T 
\ensuremath{\mathcal{M}})}       \ar[r]^{\delta_{k}} & \ensuremath{\mathrm{H}^{1}(\ensuremath{\mathcal{M}}, \ensuremath{\mathcal{S}}^{k-1} T \ensuremath{\mathcal{M}})} 
\ar[r] & \cdots }
\end{equation}
In order to show \eqref{eq:40.1}, in view of \eqref{eq:a43}, it is enough to prove that 
the boundary operator $\delta'_k$ is injective for all $k
\geq 1$ and   which is equivalent to showing that 
the boundary operator 
\begin{equation}
\delta_{k}: \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},  \ensuremath{\mathcal{S}}ym^k T \ensuremath{\mathcal{M}})}      \to  \ensuremath{\mathrm{H}^{1}(\ensuremath{\mathcal{M}}, \ensuremath{\mathcal{S}}ym^{k-1} T \ensuremath{\mathcal{M}})}
\end{equation}
is injective for every $k \geq 1$.

Further a connecting homomorphism can be expressed as the
cup product by the extension class of the corresponding
short exact  sequence.  Denote the extension class
of the following short exact sequence 
\begin{equation}
\label{eq:a49.1}
0 \to  \ensuremath{\mathcal{S}}ym^{k-1}(T \ensuremath{\mathcal{M}}) \to 
\frac{\ensuremath{\mathcal{S}}ym^k\ensuremath{\mathrm{At} (L)}}{\ensuremath{\mathcal{S}}ym^{k-2}\ensuremath{\mathrm{At} (L)}} \to \ensuremath{\mathcal{S}}ym^k(T \ensuremath{\mathcal{M}}) \to 0 
\end{equation}
by $\gamma_{k}$.

Moreover, $\gamma_{k}$ can be expressed in terms of the
first Chern class $c_1(L)$, because
the first Chern class of $c_1(L)$ is nothing  but
the extension class of the following {\bf Atiyah exact
sequence} (see \cite{A})

\begin{equation}
\label{eq:a53}
0 \to \ensuremath{\mathcal{O}_{\ensuremath{\mathcal{M}}}} \to \ensuremath{\mathrm{At} (L)} \xrightarrow{ \sigma} T \ensuremath{\mathcal{M}} \to 0,
\end{equation}
and the short exact sequence \eqref{eq:a47} is 
the $k$-th symmetric power of the Atiyah exact sequence 
\eqref{eq:a53}.

Thus, the connecting homomorphism $\delta_{k}$ can be described using the first Chern
class $c_1(L) \in \ensuremath{\mathrm{H}^{1}(\ensuremath{\mathcal{M}}, T^* \ensuremath{\mathcal{M}})}$ of the line bundle $L$. 

The cup product with $ kc_1(L)$ gives rise to a homomorphism
\begin{equation*}
\label{eq:a54}
\mu: \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{\ensuremath{\mathcal{M}}}}, \ensuremath{\mathcal{S}}ym^k T \ensuremath{\mathcal{M}})} \to \ensuremath{\mathrm{H}^{1}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^k T \ensuremath{\mathcal{M}} \otimes T^* \ensuremath{\mathcal{M}})}
\end{equation*}
Also, we have a canonical homomorphism of vector bundles
\begin{equation*}
\label{eq:a55}
\beta: \ensuremath{\mathcal{S}}ym^k T\ensuremath{\mathcal{M}} \otimes T^*\ensuremath{\mathcal{M}} \to  \ensuremath{\mathcal{S}}ym^{k-1}T \ensuremath{\mathcal{M}}
\end{equation*}
which induces a morphism of  \ensuremath{\mathbb{C}}-vector spaces
\begin{equation*}
\label{eq:a56}
\beta^*:\ensuremath{\mathrm{H}^{1}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^k T \ensuremath{\mathcal{M}}
 \otimes T^* \ensuremath{\mathcal{M}})} \to \ensuremath{\mathrm{H}^{1}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^{k-1} T \ensuremath{\mathcal{M}})}.
\end{equation*}
So, we get a morphism
\begin{equation*}
\label{eq:a57}
\tilde{\mu} = \beta^* \circ \mu: \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^k T 
\ensuremath{\mathcal{M}})} \to \ensuremath{\mathrm{H}^{1}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^{k-1} T \ensuremath{\mathcal{M}})}.
\end{equation*}
Then $\tilde{\mu} = \delta_{k}$.  Now, it 
is enough to show that $\tilde{\mu}$ is injective.


Consider the natural projection 
\begin{equation*}
\label{eq:a49}
p : T^*\ensuremath{\mathcal{M}} \longrightarrow \ensuremath{\mathcal{M}},
\end{equation*}
where $T^*\ensuremath{\mathcal{M}}$ denote the cotangent bundle of $\ensuremath{\mathcal{M}}$. Then, we have 
\begin{equation}
\label{eq:a50}
 \ensuremath{\mathrm{H}^{0}(T^*\ensuremath{\mathcal{M}},\ensuremath{\mathcal{O}_{T^*\ensuremath{\mathcal{M}}}})} = \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},p_* \ensuremath{\mathcal{O}_{T^*\ensuremath{\mathcal{M}}}})}.
\end{equation}
Moreover, using the projection formula we have 
\begin{equation}
\label{eq:a51}
p_* \ensuremath{\mathcal{O}_{T^*\ensuremath{\mathcal{M}}}} = \bigoplus_{k \geq 0}  \ensuremath{\mathcal{S}}ym^{k} T\ensuremath{\mathcal{M}}.
\end{equation}
Using \eqref{eq:a50} and \eqref{eq:a51} we get
\begin{equation}
\label{eq:a52}
\ensuremath{\mathrm{H}^{0}(T^*\ensuremath{\mathcal{M}},\ensuremath{\mathcal{O}_{T^*\ensuremath{\mathcal{M}}}})} = \bigoplus_{k \geq 0} \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}}, \ensuremath{\mathcal{S}}ym^{k} T \ensuremath{\mathcal{M}})}
\end{equation}

Now, to compute $\ensuremath{\mathrm{H}^{0}(T^*\ensuremath{\mathcal{M}},\ensuremath{\mathcal{O}_{T^*\ensuremath{\mathcal{M}}}})}$
we use the Hitchin fibration for the moduli space of 
strongly parabolic Higgs bundles as defined in \eqref{eq:a22.4}. Recall that for
any generic point $a \in \ensuremath{\mathcal{H}}_P$, we have  $h_P^{-1}(a) = A $, where
$A$ is some abelian variety (for more details see \cite{SWW}, \cite{BGL}), and we will be using this fact 
showing that $\tilde{\mu}$ is injective.

Let $g: T^*\ensuremath{\mathcal{M}} \to \ensuremath{\mathbb{C}}$ be an algebraic function. Since $T^*\ensuremath{\mathcal{M}}$ is an open subset of $\ensuremath{\mathcal{M}}_{Higgs }(r, d, \alpha)$ such that the complement has codimension  at least $2$ (see \eqref{eq:a22.3}), from
Hartog's theorem, the algebraic function $g$ is extended to an algebraic function $$\tilde{g} : \ensuremath{\mathcal{M}}_{Higgs}(r, d, \alpha) \to \ensuremath{\mathbb{C}}.$$  Then its restriction  $\tilde{g}|_{h_P^{-1}(a)}: h_P^{-1}(a) \to \ensuremath{\mathbb{C}}$ to $h_P^{-1}(a)$ is an algebraic function. Since $h_P^{-1}(a)$ is an abelian variety,  $\tilde{g}$ is a constant 
function. Therefore, on generic fibre $h^{-1}(a)$, $\tilde{g}$ is constant, and $h_P$ is proper, hence gives an algebraic function on
$\ensuremath{\mathcal{H}}_P$.    Thus, any algebraic function on $T^*\ensuremath{\mathcal{M}}$ descends to an algebraic function on $\ensuremath{\mathcal{H}}_P$.

Set $\ensuremath{\mathcal{P}} = \mbox{d}( \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{H}}_P,\ensuremath{\mathcal{O}_{\ensuremath{\mathcal{H}}_P}})}) \subset  \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{H}}_P,\Omega^1_{\ensuremath{\mathcal{H}}_P})}$ the space of all exact algebraic $1$-form.
Define a map 
\begin{equation}
\label{eq:a53.1}
\theta: \ensuremath{\mathrm{H}^{0}(T^*\ensuremath{\mathcal{M}},\ensuremath{\mathcal{O}_{ T^* \ensuremath{\mathcal{M}}}})} \to \ensuremath{\mathcal{P}}
\end{equation}
by $g \mapsto d \tilde{g}$, where $\tilde{g}$ is the function which is defined by descent of $g$.  Then $\theta$ is an isomorphism.

From \eqref{eq:a52} and \eqref{eq:a53.1}, we have
\begin{equation}
\label{eq:a54.2}
\theta:\bigoplus_{k \geq 0}
\ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^{k} T \ensuremath{\mathcal{M}})} \to \ensuremath{\mathcal{P}}
\end{equation}
which is an isomorphism.
Let us denote the restriction of $h_P$ on $T^*\ensuremath{\mathcal{M}}$ by  $h'_{P}$.

Let $T_{h'_P} = T_{T^* \ensuremath{\mathcal{M}} / \ensuremath{\mathcal{H}}_P} = \ensuremath{\mathcal{K}er (\mbox{d}h'_P)}$
be the relative tangent sheaf on $T^*\ensuremath{\mathcal{M}}$,
where $$\mbox{d}h'_P: T(T^*\ensuremath{\mathcal{M}}) \to {h'}_P^*T \ensuremath{\mathcal{H}}_P$$ morphism 
of bundles.

 Note that 
$ \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{H}}_P,\Omega^1_{\ensuremath{\mathcal{H}}_P})} \subset  \ensuremath{\mathrm{H}^{0}(T^*\ensuremath{\mathcal{M}},T_{h'_P})} $, and hence from \eqref{eq:a54.2}, we have
an injective homomorphism
\begin{equation*}
\label{eq:a55.1}
\nu: \ensuremath{\mathcal{P}} = \bigoplus_{k \geq 0} \theta(
\ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^{k} T \ensuremath{\mathcal{M}})}) \to \ensuremath{\mathrm{H}^{0}(T^*\ensuremath{\mathcal{M}},T_{h'_P})}.
\end{equation*}

Consider the morphism 

$$\ensuremath{\mathrm{H}^{0}(T^*\ensuremath{\mathcal{M}},T_{h'_P})} \to \ensuremath{\mathrm{H}^{1}(T^*\ensuremath{\mathcal{M}},T_{h'_P} \otimes T^* T^* \ensuremath{\mathcal{M}})}$$ defined 
by taking cup product with the first Chern class $c_1(p^* L) \in  \ensuremath{\mathrm{H}^{1}(T^*\ensuremath{\mathcal{M}}, T^* T^* \ensuremath{\mathcal{M}})}$.

Using the pairing $$T_{h'_P} \otimes T^* T^* \ensuremath{\mathcal{M}} \to \ensuremath{\mathcal{O}_{T^* \ensuremath{\mathcal{M}}}},$$ we get a homomorphism
\begin{equation*}
\label{eq:a56.1}
\eta: \ensuremath{\mathrm{H}^{0}(T^*\ensuremath{\mathcal{M}},T_{h'_P})} \to \ensuremath{\mathrm{H}^{1}(T^*\ensuremath{\mathcal{M}},\ensuremath{\mathcal{O}_{T^*\ensuremath{\mathcal{M}}}})}
\end{equation*}

Since $c_1(p^* L) = p^*c_1 (L)$, we have
\begin{equation}
\label{eq:a57.1}
k \eta \circ \nu \circ \theta(\omega_k) = \tilde{\mu}(\omega_k),
\end{equation}
for all $\omega_k \in \ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^{k} T \ensuremath{\mathcal{M}})})$.
Since $\nu$ and $\theta$ are injective homomorphisms, it is enough to 
show that $\eta|_{\nu(\ensuremath{\mathcal{P}})}$ is injective homomorphism. 


Let $\omega \in \ensuremath{\mathcal{P}} \setminus \{0\}$ be a non-zero
exact $1$-form. Choose $a \in \ensuremath{\mathcal{H}}_P$ such that $\omega(a) \neq 0$. 
In view of \eqref{eq:a22.1} and \eqref{eq:a22.3}, the generic fibre has the form
 $${h'_P}^{-1}(a) = A \setminus F,$$ where $A$ is an abelian variety and $F$ is a subvariety of $A$ such that $\mbox{codim}(F,A) \geq 2$.
Now, $\eta(\nu(\omega)) \in \ensuremath{\mathrm{H}^{1}(T^*\ensuremath{\mathcal{M}},\ensuremath{\mathcal{O}_{T^*\ensuremath{\mathcal{M}}}})}$ and we have restriction map $$\ensuremath{\mathrm{H}^{1}(T^*\ensuremath{\mathcal{M}},\ensuremath{\mathcal{O}_{T^*\ensuremath{\mathcal{M}}}})} \to \ensuremath{\mathrm{H}^{1}({h'_P}^{-1}(a),\ensuremath{\mathcal{O}_{{h'_P}^{-1}(a)}})}.$$
Since $ \omega(a) \neq 0$, $\eta(\nu(\omega)) \in \ensuremath{\mathrm{H}^{1}({h'_P}^{-1}(a),\ensuremath{\mathcal{O}_{{h'_P}^{-1}(a)}})}$.
Because of the following isomorphisms
\begin{equation*}
\label{eq:a58}
 \ensuremath{\mathrm{H}^{1}({h'_P}^{-1}(a),\ensuremath{\mathcal{O}_{{h'_P}^{-1}(a)}})} \cong  \ensuremath{\mathrm{H}^{1}(A,\ensuremath{\mathcal{O}_{A}})} \cong  \ensuremath{\mathrm{H}^{0}(A,TA)},
\end{equation*}
it follows that $\eta(\nu(\omega)) \neq 0$.
This completes the proof.

\label{cor:1}
Let $L$ be an ample line bundle over $\ensuremath{\mathcal{M}}(r, d, \alpha)$. Then,
\begin{equation*}
\label{eq:dif}
\ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{D}}^k(L))} = \ensuremath{\mathbb{C}}
\end{equation*}
for every $k \geq 0$.

\mbox{}
\label{rmk:2}
\begin{enumerate}
\item Note that the above 
 Theorem \ref{thm:2} is equivalent to proving 
 $$\ensuremath{\mathrm{H}^{0}(\ensuremath{\mathcal{M}},\ensuremath{\mathcal{S}}ym^k\ensuremath{\mathrm{At} (L)})} = \ensuremath{\mathbb{C}}$$
 for every $k \geq 0$.

\item Since $\ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha)$ and $\ensuremath{\mathcal{C}}(L)$ are 
$T^*\ensuremath{\mathcal{M}}(r, d, \alpha)$-torsors,  there is a natural 
question to ask,
\begin{question}
\label{q:1}
Does there exist an ample line bundle $L$ over $\ensuremath{\mathcal{M}}(r, d, \alpha)$ and an isomorphism 
$$\varpi : \ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha) \longrightarrow \ensuremath{\mathcal{C}}(L)$$ of varieties 
such that the following diagram 
\begin{equation*}
\xymatrix{
\ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha) \ar[r]^{\varpi} \ar[d]^{\pi} & \ensuremath{\mathcal{C}}(L) \ar[dl]^{\Psi} \\
\ensuremath{\mathcal{M}}(r, d, \alpha) \\
}
\end{equation*}
commutes ?
\end{question}

If the answer of the Question \ref{q:1} is in affirmative, then from the Theorem \ref{thm:2}, the moduli space $\ensuremath{\mathcal{M}}_{pc}(r, d, \alpha)$ does not admit 
any non-constant algebaric function.

\end{enumerate}

\label{q:1}
Does there exist an ample line bundle $L$ over $\ensuremath{\mathcal{M}}(r, d, \alpha)$ and an isomorphism 
$$\varpi : \ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha) \longrightarrow \ensuremath{\mathcal{C}}(L)$$ of varieties 
such that the following diagram 
\begin{equation*}
\xymatrix{
\ensuremath{\mathcal{M}}'_{pc}(r, d, \alpha) \ar[r]^{\varpi} \ar[d]^{\pi} & \ensuremath{\mathcal{C}}(L) \ar[dl]^{\Psi} \\
\ensuremath{\mathcal{M}}(r, d, \alpha) \\
}
\end{equation*}
commutes ?

\label{prop:3}
There exists an algebraic vector bundle 
\begin{equation}
\label{eq:a59}
\Psi :\ensuremath{\mathcal{V}} \longrightarrow \ensuremath{\mathcal{M}}(r,\alpha, \xi)
\end{equation}
such that 
$\ensuremath{\mathcal{M}}'_{pc}(r, \alpha, \xi)$ is embedded in $\ensuremath{\mathbf{P}}(\ensuremath{\mathcal{V}})$ with $$
{\bf H_0} = 
\ensuremath{\mathbf{P}} (\ensuremath{\mathcal{V}}) \setminus \ensuremath{\mathcal{M}}'_{pc}(r, \alpha, \xi)$$ as a smooth divisor at infinity.

\label{prop:4}
